pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 warpTime, uint256 rollNum) public {
        // Keep amount wide: any value except exactly 10 ether could reveal the bug if the mutant accepts it.
        // Warp time to be strictly greater than 0 to satisfy block.timestamp > pastBlockTime.
        vm.assume(warpTime > 0);
        vm.warp(warpTime);
        // Roll to a block number that is a multiple of 15 so the transfer branch is taken.
        vm.assume(rollNum % 15 == 0);
        vm.roll(rollNum);
        // Fund the contract with exactly 10 ether so the reference call succeeds.
        vm.deal(address(c), 10 ether);
        // Deal the fuzzed amount to this test contract and send it to fallback.
        vm.deal(address(this), amount);
        uint256 balanceBefore = address(c).balance;
        bool refSuccess;
        try c.fallback{value: amount}() {
            refSuccess = true;
        } catch {
            refSuccess = false;
        }
        uint256 balanceAfter = address(c).balance;
        // General rule: If the call succeeds, the contract balance must change exactly as the reference expects.
        // For the reference, call succeeds only if amount == 10 ether, and post-transfer balance is 0 (entire balance transferred).
        // For the mutant, call succeeds for any amount, and post-transfer balance can be non-zero if amount != 10 ether.
        // Assert: If the call succeeds, the balance after must be 0 (entire balance transferred).
        // This holds for ALL successful calls on the reference (only possible when amount == 10 ether) and
        // fails on the mutant when amount != 10 ether (mutant succeeds but balanceAfter is amount, not 0).
        assertTrue(!refSuccess || balanceAfter == 0);
    }
}

