pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 blockNumber, uint256 timestamp, uint256 pastTimestamp) public {
        // Restrict to admissible domains
        amount = bound(amount, 0, 1000 ether);
        blockNumber = bound(blockNumber, 1, type(uint256).max);
        timestamp = bound(timestamp, 1, type(uint256).max);
        pastTimestamp = bound(pastTimestamp, 0, timestamp - 1);

        // Set up the reference contract's state: deploy a fresh one and set its pastBlockTime
        // We need to set pastBlockTime to a past timestamp less than timestamp, so the require(block.timestamp > pastBlockTime) passes
        // But pastBlockTime is set only inside fallback, which also requires msg.value == 10 ether.
        // To set pastBlockTime non-zero for the reference, we must call fallback with 10 ether and a higher timestamp.
        // We initialize C with a call that sets pastBlockTime using a minimal value > 0
        // We'll use a separate initialization step: vm.warp to pastTimestamp+1, vm.deal, prank, call with 10 ether
        // This sets pastBlockTime = pastTimestamp + 1
        if (pastTimestamp + 1 < timestamp) {
            vm.warp(pastTimestamp + 1);
            vm.roll(1);
            vm.deal(address(this), 10 ether);
            c.fallback{value: 10 ether}();
        }

        // Now set up the actual call
        vm.warp(timestamp);
        vm.roll(blockNumber);
        vm.deal(address(this), amount);

        // Capture reference behavior
        bool refOk;
        uint256 refBalanceBefore = address(c).balance;
        try c.fallback{value: amount}() {
            refOk = true;
        } catch {
            refOk = false;
        }
        uint256 refBalanceAfter = address(c).balance;

        // IGNORE: The bug removes the msg.value == 10 ether check.
        // The property we test: If the reference succeeds (refOk == true), then amount MUST be 10 ether.
        // The mutant would succeed for any amount, violating this.
        // However we must observe c's public surface: we assert that whenever the call succeeds, amount == 10 ether.
        // The assertion uses a boolean derived from the behavior.
        assertTrue(!refOk || amount == 10 ether);
    }
}

