pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 value, uint256 blockNum, uint256 warpTo) public {
        // Bound the value to a reasonable range to avoid overflow in balance calculations
        value = bound(value, 0, 100 ether);
        // Ensure the timestamp is strictly increasing; use a future timestamp
        vm.assume(warpTo > block.timestamp);
        vm.warp(warpTo);
        // Set the block number for the mod 15 condition
        vm.roll(blockNum);

        // Ensure we have enough ether for the call
        address actor = address(0x1234);
        vm.deal(actor, value);

        uint256 balanceBefore = address(c).balance;
        bool ok;
        vm.prank(actor);
        try c.fallback{value: value}() {
            ok = true;
        } catch {
            ok = false;
        }
        uint256 balanceAfter = address(c).balance;

        // The invariant: if the call did not revert, the balance must increase by exactly the sent value.
        // The reference reverts when value != 10 ether (so ok is false), and the balance stays the same.
        // The mutant never reverts due to msg.value, so for value != 10 ether, ok is true and the balance
        // increases by value, which violates the condition (since balanceBefore + value != balanceBefore).
        // But we must express this as a logical property that holds for the reference for ALL inputs
        // and fails for the mutant for SOME input.
        // For the reference: ok implies (balanceAfter == balanceBefore + value).
        // For the mutant: when value != 10 ether, ok is true but (balanceAfter == balanceBefore + value) may be
        // false because the contract's own balance is transferred away when block.number % 15 == 0.
        // Thus, the assertion that "it is NOT the case that (ok AND (balanceAfter != balanceBefore + value))"
        // is satisfied by the reference (since whenever ok is true, balanceAfter == balanceBefore + value)
        // and broken by the mutant (since for some value != 10 ether, ok is true but balanceAfter may differ
        // if the transfer triggers).
        // Simpler: assert that if the call succeeds (ok), the balance increases exactly by msg.value.
        // Form: assertTrue(!ok || (balanceAfter == balanceBefore + value));
        assertTrue(!ok || (balanceAfter == balanceBefore + value));
    }
}

