pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNum, uint8 extraCalls) public {
        // Constrain block number to be divisible by 15 to trigger transfer
        blockNum = bound(blockNum, 1, 1e9);
        vm.assume(blockNum % 15 == 0);
        // At least 1 extra call to reveal the difference
        extraCalls = uint8(bound(extraCalls, 1, 10));

        // Move to the chosen block
        vm.roll(blockNum);
        vm.warp(0);

        address alice = makeAddr("alice");
        vm.deal(alice, 10000 ether);

        // First call succeeds in both versions
        vm.prank(alice);
        c.fallback{value: 10 ether}();

        // In P, extra calls in the same block revert because block.timestamp == pastBlockTime
        // In M, they succeed and may attempt transfers; eventually a transfer can fail if balance < 10 ether
        uint256 counter = 0;
        for (uint256 i = 0; i < extraCalls; i++) {
            vm.prank(alice);
            // low-level call to catch revert without blocking the loop
            (bool ok,) = address(c).call{value: 10 ether}("");
            if (ok) {
                counter++;
            } else {
                // revert caught, balance unchanged
            }
        }

        // Property: At most one fallback call per block can succeed in the reference C.
        // The mutant M can have counter > 1 (multiple successful calls in the same block),
        // but the reference C will always have counter == 0 (the second call reverts),
        // so counter <= 1 holds for P but fails for M.
        assertTrue(counter <= 1);
    }
}

