pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 roll) public {
        // Keep roll in admissible range where block.number % 15 == 0 triggers a transfer
        uint256 blockNumber = bound(roll, 15, type(uint256).max - (type(uint256).max % 15));
        vm.roll(blockNumber);
        // Warp to a timestamp > 0 so that require(block.timestamp > pastBlockTime) passes on first call
        vm.warp(1);
        // Fund two distinct callers with exactly 10 ether each
        address actor1 = address(1);
        address actor2 = address(2);
        vm.deal(actor1, 10 ether);
        vm.deal(actor2, 10 ether);
        // First successful call from actor1 in blockNumber
        vm.prank(actor1);
        (bool success1,) = address(c).call{value: 10 ether}("");
        // Second call from actor2 in the same block
        vm.prank(actor2);
        (bool success2,) = address(c).call{value: 10 ether}("");
        // Reference C: second call reverts because block.timestamp > pastBlockTime is false => success2 is false, balance remains >= 10 ether
        // Mutant M: second call succeeds, triggers second transfer, balance becomes 0 ether
        bool balanceSufficient = address(c).balance >= 10 ether;
        assertTrue(balanceSufficient);
    }
}

