pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNum, uint256 warpTime) public {
        uint256 AMOUNT = 10 ether;
        address sender = address(0x1234);

        vm.assume(blockNum > 0);
        vm.assume(warpTime > 0);

        vm.deal(sender, AMOUNT);
        vm.roll(blockNum);
        vm.warp(warpTime);

        vm.prank(sender);
        c.fallback{value: AMOUNT}();

        bool divisibleBy15 = (blockNum % 15 == 0);
        uint256 bal = address(c).balance;

        // General rule: After a successful fallback call, the contract's
        // ETH balance is exactly 0 if block.number is divisible by 15
        // and exactly AMOUNT (10 ether) otherwise.
        // The mutant breaks this when block.number is NOT divisible by 15:
        // it then transfers the balance (so bal==0), whereas it should be 10 ether.
        // When block.number IS divisible by 15, both versions correctly transfer (bal==0).
        assertTrue(
            (divisibleBy15 && bal == 0) || (!divisibleBy15 && bal == AMOUNT)
        );
    }
}

